import {emitterContext} from './emitters.js';
import {cents,currency} from './ledger.js';
const canonical=s=>{s=String(s).trim().toUpperCase().replaceAll(' ','');let m=s.match(/^(\d+)[-/](20\d\d)$/);if(m)return `F:${m[2]}:${Number(m[1])}`;m=s.match(/^([A-Z]+)[-/](20\d\d)[-/](\d+)$/);return m?`${m[1]}:${m[2]}:${Number(m[3])}`:s;};
export function createImportView(ctx){
 const {shell,heading,esc,icon,toast,modal,getDb,command,onDone,onCancel}=ctx;
 let preview=null,file=null,reference=false,step='invoices',busy=false;
 const selectedRows=()=>preview?.rows.filter(r=>r.selected)||[];
 const selectedPayments=()=>preview?.payments.filter(p=>p.selected)||[];
 function render(){shell(heading('Importar histórico','Emisor de destino: '+esc(getDb().company.name)+' · '+esc(getDb().company.nif),`<button class="btn" data-im="cancel">${icon('back')} Volver a Análisis</button>`)+`<div class="import-steps"><span class="${!preview?'current':''}">1 · Elegir Excel</span><span class="${preview&&step==='invoices'?'current':''}">2 · Revisar facturas</span><span class="${preview&&step==='payments'?'current':''}">3 · Revisar cobros</span><span>4 · Confirmar</span></div>${preview?review():chooser()}`,'Análisis · Importación');const toggle=document.querySelector('#im-all-invoices');if(toggle)toggle.indeterminate=preview.rows.some(r=>r.selected)&&!preview.rows.every(r=>r.selected);}
 function chooser(){return `<section class="panel import-chooser"><div class="hint-icon">${icon('invoice')}</div><h2>Tu Excel, con una revisión previa</h2><p>La lectura no modifica tus datos. Se separarán facturas, anotaciones y transferencias agrupadas para que decidas qué incorporar.</p><div class="actions">${emitterContext.active?.isOriginal?`<button class="btn primary" data-im="reference" ${busy?'disabled':''}>${busy?'Leyendo Excel…':'Revisar «AA ingresos ADG 2026.xlsx»'}</button>`:''}<button class="btn" data-im="choose" ${busy?'disabled':''}>Seleccionar otro Excel</button><input type="file" id="import-file" accept=".xlsx" hidden></div><div class="notice">Las hojas se revisan por separado. No se incorporan subtotales, fórmulas ejecutables ni filas auxiliares como facturas. Los datos quedan en este equipo.</div></section>`;}
 function reviewedCount(){return selectedRows().filter(r=>r.issues.length&&!r.reviewed).length;}
 function review(){const existing=getDb().invoices.filter(i=>i.status==='issued'&&!i.isDemo&&!i.voided);return `<section class="panel import-header"><div><h2>${esc(preview.filename)}</h2><p>${preview.rows.length} filas de facturas · ${preview.payments.length} propuestas de cobro · ${preview.skippedRows.length} filas auxiliares excluidas</p></div><div class="field"><label for="im-sheet">Hoja del libro</label><select id="im-sheet">${preview.sheets.map(s=>`<option ${preview.sheet===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div><button class="btn" data-im="reset">Cambiar archivo</button></section><div class="notice">Las transferencias son propuestas: solo se guardarán las que selecciones y marques como revisadas. Las facturas sin cobros confirmados empezarán sin pago registrado.</div><div class="tabs import-tabs"><button class="tab ${step==='invoices'?'active':''}" data-im="invoices">Facturas (${preview.rows.length})</button><button class="tab ${step==='payments'?'active':''}" data-im="payments">Transferencias (${preview.payments.length})</button></div>${step==='invoices'?invoiceReview(existing):paymentReview()}<section class="panel import-confirm-bar"><div><strong id="im-summary">${selectedRows().length} facturas seleccionadas · ${selectedPayments().length} cobros seleccionados</strong><p id="im-pending">${reviewedCount()} filas con incidencias pendientes de confirmar.</p></div><button class="btn primary" data-im="confirm">Revisar e importar ${icon('arrow')}</button></section>`;}
 function invoiceReview(existing){return `<section class="panel"><div class="toolbar"><div><h3>Comprueba fechas, importes y destinatarios</h3><p class="summary-note">Se conserva el número original. Las facturas ya existentes se contrastarán para evitar duplicados.</p></div><label class="check-label"><input type="checkbox" id="im-all-invoices" ${preview.rows.every(r=>r.selected)?'checked':''}>Seleccionar todas</label><button class="btn ghost" data-im="select-none">Deseleccionar todas</button></div><div class="tablewrap import-table-wrap"><table class="import-table"><thead><tr><th></th><th>Fila</th><th>Número</th><th>Fecha emisión</th><th>Cliente</th><th class="num">Base €</th><th class="num">IVA €</th><th class="num">Total €</th><th>Revisión</th></tr></thead><tbody>${preview.rows.map(r=>{const duplicate=existing.find(i=>[i.number,...(i.numberHistory||[]).map(h=>h.oldNumber)].some(n=>canonical(n)===canonical(r.number)));return `<tr class="${r.issues.length?'has-issue':''}"><td><input type="checkbox" class="small-check" data-im-row="${r.row}" data-im-field="selected" ${r.selected?'checked':''} aria-label="Importar fila ${r.row}"></td><td>${r.row}</td><td><input data-im-row="${r.row}" data-im-field="number" value="${esc(r.number)}" aria-label="Número fila ${r.row}"></td><td><input type="date" data-im-row="${r.row}" data-im-field="date" value="${esc(r.date)}" aria-label="Fecha fila ${r.row}"></td><td><input data-im-row="${r.row}" data-im-field="client" value="${esc(r.client)}" aria-label="Cliente fila ${r.row}"></td>${['baseCents','vatCents','totalCents'].map(k=>`<td><input inputmode="decimal" data-im-row="${r.row}" data-im-field="${k}" value="${(r[k]/100).toFixed(2)}" aria-label="${k==='baseCents'?'Base':k==='vatCents'?'IVA':'Total'} fila ${r.row}"></td>`).join('')}<td>${r.issues.length?`<label class="check-label"><input type="checkbox" data-im-row="${r.row}" data-im-field="reviewed" ${r.reviewed?'checked':''}>Revisada</label>`:duplicate?'<small class="muted">Número ya existente</small>':'<span class="badge">Sin incidencias</span>'}</td></tr>${r.issues.length?`<tr class="import-issue-row"><td></td><td colspan="8"><strong>Revisar:</strong> ${r.issues.map(esc).join(' · ')}<details><summary>Concepto y anotación original</summary><p>${esc(r.description)}</p><p>${esc(r.paymentNote||'Sin anotación de cobro')}</p></details></td></tr>`:''}`;}).join('')}</tbody></table></div><div class="tablefoot"><span>Los importes históricos se conservan en céntimos; no se recalculan suponiendo un IVA único.</span><button class="btn" data-im="payments">Continuar con los cobros ${icon('arrow')}</button></div></section>`;}
 function defaultAllocations(p){if(p.allocations)return p.allocations;let remaining=p.amountCents;const members=preview.rows.filter(r=>p.rows.includes(r.row));p.allocations=members.map(r=>{let n=r.totalCents;if(p.method==='confirming'){n=Math.max(0,Math.min(n,remaining));remaining-=n;}return {row:r.row,amountCents:n};});return p.allocations;}
 function paymentReview(){return `<div class="import-payment-list"><div class="notice">Una transferencia puede pagar facturas de varios clientes. Comprueba el pagador, el importe bancario y su reparto. Los ajustes de confirming se registran después de importar, desde el historial de la factura.</div>${preview.payments.map(p=>`<article class="panel import-payment" data-im-payment-card="${esc(p.id)}"><div class="sectionhead"><label class="check-label"><input type="checkbox" data-im-pay="${esc(p.id)}" data-im-field="selected" ${p.selected?'checked':''}><strong>Incorporar este ingreso</strong></label><span class="badge ${p.issues.length?'draft':''}">${p.rows.length} factura${p.rows.length===1?'':'s'}</span></div><div class="fields"><div class="field"><label>Importe recibido (€)</label><input inputmode="decimal" data-im-pay="${esc(p.id)}" data-im-field="amountCents" value="${(p.amountCents/100).toFixed(2)}" aria-label="Importe transferencia ${p.id}"></div><div class="field"><label>Fecha de ingreso</label><input type="date" data-im-pay="${esc(p.id)}" data-im-field="date" value="${esc(p.date)}" aria-label="Fecha transferencia ${p.id}"></div><div class="field"><label>Cliente que paga</label><input value="${esc(p.payer)}" readonly aria-label="Cliente que paga la transferencia ${esc(p.id)}"><small>Solo se aplican sus facturas.</small></div><div class="field"><label>Cuenta receptora</label><input data-im-pay="${esc(p.id)}" data-im-field="account" value="${esc(p.account)}" aria-label="Cuenta transferencia ${p.id}"></div><div class="field full"><label>Referencia / anotación bancaria</label><textarea data-im-pay="${esc(p.id)}" data-im-field="reference" aria-label="Referencia transferencia ${p.id}">${esc(p.reference)}</textarea></div></div><div class="import-allocations">${defaultAllocations(p).map(a=>{const r=preview.rows.find(r=>r.row===a.row);return `<div><span><strong>${esc(r.number)}</strong> · ${esc(r.client)}<small>Fila ${r.row} · Total ${currency(r.totalCents)}</small></span><input inputmode="decimal" data-im-allocation="${esc(p.id)}" data-im-row-number="${a.row}" value="${(a.amountCents/100).toFixed(2)}" aria-label="Aplicar transferencia a fila ${a.row}"></div>`;}).join('')}</div><div class="import-payment-summary" data-im-summary="${esc(p.id)}">${paymentSummary(p)}</div>${p.issues.length?`<div class="notice warning">${p.issues.map(esc).join('<br>')}</div>`:''}<label class="check-label reviewed-receipt"><input type="checkbox" data-im-pay="${esc(p.id)}" data-im-field="reviewed" ${p.reviewed?'checked':''}>He revisado el ingreso y las facturas que liquida.</label></article>`).join('')||'<section class="panel empty"><h3>No hay anotaciones de cobro con fecha en esta hoja</h3><p>Podrás registrar las transferencias manualmente después de incorporar las facturas.</p></section>'}</div>`;}
 function paymentSummary(p){const sum=defaultAllocations(p).reduce((n,a)=>n+a.amountCents,0),diff=p.amountCents-sum;return `Aplicado: <strong>${currency(sum)}</strong> · ${diff>=0?'Saldo sin aplicar':'Exceso sobre el ingreso'}: <strong>${currency(Math.abs(diff))}</strong>${diff!==0&&Math.abs(diff)<=2?' · Ajuste automático de redondeo':''}`;}
 async function load(sheet){busy=true;render();try{let response;if(reference)response=await fetch('/api/import/reference',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sheet})});else response=await fetch('/api/import/preview',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Filename':encodeURIComponent(file.name),'X-Sheet':encodeURIComponent(sheet||'')},body:file});const data=await response.json();if(!response.ok)throw Error(data.error);preview=data;step='invoices';}catch(e){toast(e.message);}finally{busy=false;render();}}
 function updateSummary(){const el=document.querySelector('#im-summary');if(el)el.textContent=`${selectedRows().length} facturas seleccionadas · ${selectedPayments().length} cobros seleccionados`;const pending=document.querySelector('#im-pending');if(pending)pending.textContent=`${reviewedCount()} filas con incidencias pendientes de confirmar.`;}
 function confirm(){if(!selectedRows().length)throw Error('Selecciona al menos una factura.');if(reviewedCount())throw Error('Corrige las incidencias y marca como revisadas las filas seleccionadas.');if(selectedPayments().some(p=>!p.reviewed))throw Error('Confirma la revisión de cada cobro seleccionado.');for(const p of selectedPayments()){const allocations=defaultAllocations(p);if(allocations.some(a=>a.amountCents>0&&!selectedRows().some(r=>r.row===a.row)))throw Error('Selecciona las facturas de cada cobro o elimina sus importes del reparto.');if(allocations.reduce((n,a)=>n+a.amountCents,0)-p.amountCents>2)throw Error('Un reparto supera el ingreso: revisa los importes de las transferencias.');}
 modal.className='';modal.innerHTML=`<h2>Confirmar importación</h2><p>Se revisarán ${selectedRows().length} facturas y ${selectedPayments().length} cobros de la hoja ${esc(preview.sheet)}. Las facturas que ya existan se contrastarán y no se duplicarán. Las filas sin cobro confirmado quedarán pendientes.</p><div class="notice">Las fechas, números e importes históricos se conservarán. Se guardará la procedencia de cada fila y una entrada en el historial.</div><div id="import-final-error" class="form-error" role="alert"></div><div class="actions"><button class="btn" data-im="close-confirm">Volver a revisar</button><button class="btn primary" data-im="commit">Confirmar e incorporar</button></div>`;modal.showModal();}
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-im]');if(!b)return;try{switch(b.dataset.im){case'cancel':onCancel();break;case'reference':reference=true;file=null;await load();break;case'choose':document.querySelector('#import-file').click();break;case'reset':preview=null;step='invoices';render();break;case'select-none':preview.rows.forEach(r=>r.selected=false);render();break;case'invoices':step='invoices';render();break;case'payments':step='payments';render();break;case'confirm':confirm();break;case'close-confirm':modal.close();break;case'commit':b.disabled=true;try{const payload={operationId:preview.operationId||=crypto.randomUUID(),type:'import',previewId:preview.id,rows:preview.rows,payments:preview.payments.map(p=>({...p,allocations:defaultAllocations(p)}))};await command(payload);modal.close();toast('Histórico incorporado y guardado en este equipo');preview=null;onDone();}catch(err){document.querySelector('#import-final-error').textContent=err.message;b.disabled=false;}break;}}catch(err){toast(err.message);}});
 document.addEventListener('change',async e=>{const el=e.target;if(el.id==='import-file'&&el.files[0]){file=el.files[0];reference=false;await load();}if(el.id==='im-sheet'){const sheet=el.value;preview=null;await load(sheet);}if(el.id==='im-all-invoices'){preview.rows.forEach(r=>r.selected=el.checked);render();}if(el.dataset.imField&&el.type==='checkbox')updateValue(el);});
 document.addEventListener('input',e=>{const el=e.target;if(el.dataset.imField&&el.type!=='checkbox')updateValue(el);if(el.dataset.imAllocation){const p=preview.payments.find(p=>p.id===el.dataset.imAllocation),a=defaultAllocations(p).find(a=>a.row===Number(el.dataset.imRowNumber));a.amountCents=cents(el.value);const summary=document.querySelector(`[data-im-summary="${esc(p.id)}"]`);if(summary)summary.innerHTML=paymentSummary(p);}});
 function updateValue(el){if(!preview)return;const target=el.dataset.imRow?preview.rows.find(r=>r.row===Number(el.dataset.imRow)):preview.payments.find(p=>p.id===el.dataset.imPay);if(!target)return;const key=el.dataset.imField;target[key]=el.type==='checkbox'?el.checked:key.endsWith('Cents')?cents(el.value):el.value;if(el.dataset.imPay){const summary=document.querySelector(`[data-im-summary="${esc(target.id)}"]`);if(summary)summary.innerHTML=paymentSummary(target);}updateSummary();}
 return {render};
}
